class MobileOptimizer{constructor(){this.isMobile=!1,this.isSlowConnection=!1,this.isDataSaver=!1,this.isIOS=!1}init(){if(this.detectDevice(),this.detectConnection(),this.applyOptimizations(),"connection"in navigator){const i=navigator.connection||navigator.mozConnection||navigator.webkitConnection;i&&i.addEventListener("change",()=>{this.detectConnection(),this.applyOptimizations()})}}detectDevice(){this.isMobile=window.innerWidth<=768,this.isIOS=/iPad|iPhone|iPod/.test(navigator.userAgent)&&!window.MSStream,this.isMobile&&document.body.classList.add("is-mobile"),this.isIOS&&document.body.classList.add("is-ios")}detectConnection(){if("connection"in navigator){const i=navigator.connection||navigator.mozConnection||navigator.webkitConnection;if(i){const t=["slow-2g","2g","3g"];this.isSlowConnection=t.includes(i.effectiveType),this.isDataSaver=!0===i.saveData}}}applyOptimizations(){this.isIOS&&this.applyIOSFixes(),this.isSlowConnection||this.isDataSaver?this.applySlowConnectionOptimizations():this.removeSlowConnectionOptimizations(),this.isMobile&&this.applyMobileOptimizations()}applyIOSFixes(){const i=()=>{const i=.01*window.innerHeight;document.documentElement.style.setProperty("--vh",`${i}px`)};i(),window.addEventListener("resize",i),window.addEventListener("orientationchange",()=>{setTimeout(i,100)})}applySlowConnectionOptimizations(){document.body.classList.add("slow-connection"),window.DISABLE_PRELOAD=!0,document.querySelectorAll('link[rel="prefetch"]').forEach(i=>i.remove())}removeSlowConnectionOptimizations(){document.body.classList.remove("slow-connection"),window.DISABLE_PRELOAD=!1}applyMobileOptimizations(){document.documentElement.style.setProperty("--transition-normal","200ms ease"),window.MOBILE_OBSERVER_MARGIN="50px"}}export const mobileOptimizer=new MobileOptimizer;